import{_ as l,o as e,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Developer Summit - Crimson SeaStore","description":"","frontmatter":{"title":"Ceph Developer Summit - Crimson SeaStore","date":"2025-09-12T00:00:00.000Z","updated":"2025-09-12T00:00:00.000Z","tags":["Ceph","分布式存储","Crimson","SeaStore","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Summit_-_Crimson_SeaStore.md","filePath":"posts/2025/Ceph_Developer_Summit_-_Crimson_SeaStore.md","lastUpdated":1780459816000}'),t={name:"posts/2025/Ceph_Developer_Summit_-_Crimson_SeaStore.md"};function s(n,o,p,a,g,m){return e(),i("div",null,[...o[0]||(o[0]=[r("<p>Ceph开发者峰会-Crimson SeaStore会议纪要</p><p><strong>会议主题</strong>: Crimson EU版本（伞形版本）规划与进展</p><p><strong>日期</strong>: [会议日期]</p><p><strong>参会人员</strong>: Matan, Jose, Sam, Radic等核心开发成员</p><p><strong>会议目标</strong>:</p><ul><li>回顾Crimson在EU版本（V21）中的目标功能、已知问题及优化方向。</li><li>讨论关键技术进展，包括PG管理、性能优化、后端存储支持等。</li><li>确定后续行动计划。</li></ul><p><strong>主要议题与讨论</strong>:</p><ol><li><p><strong>PG分裂与合并（PG Splitting &amp; Merging）</strong>:</p><ul><li>PG分裂功能已合并至<code>main</code>分支，正在进行稳定性测试。</li><li>PG合并功能开发将在稳定性验证后推进。</li></ul></li><li><p><strong>Crimson构建类型分离</strong>:</p><ul><li>将Crimson构建分为<code>debug</code>和<code>release</code>两种类型，分别用于开发调试和生产环境。</li></ul></li><li><p><strong>后端存储支持（Systore vs. Bluestore）</strong>:</p><ul><li>在EU版本中支持Systore作为Crimson的默认后端存储。</li><li>部分基础支持已合并，首次通过<code>cephadm</code>部署Systore的测试任务成功运行。</li></ul></li><li><p><strong>QoS与MClock调度</strong>:</p><ul><li>PR已提交，但依赖项（如DMClock子模块的垃圾回收线程适配）待解决。</li><li>需调整Crimson架构以兼容MClock的异步特性。</li></ul></li><li><p><strong>文档与用户体验优化</strong>:</p><ul><li>新增用户指南，仅包含部署、测试等必要信息。</li><li>完整分离文档计划在EU版本中完成。</li></ul></li><li><p><strong>性能基准测试与发布</strong>:</p><ul><li>开始定期发布Crimson性能数据，包括IOPS、延迟等指标。</li><li>4K随机读场景中Crimson优于Classic，但随机写仍需优化。</li></ul></li><li><p><strong>其他功能开发</strong>:</p><ul><li>EC Pool支持、RGW支持、混合集群（Crimson + Classic OSD）支持、Scrub增强等。</li></ul></li></ol><p><strong>性能优化专题（Sam分享）</strong>:</p><ul><li>随机写性能瓶颈分析，改进Journal批处理，提升大块写入效率。</li><li>并发优化，增加后台操作的并行度。</li></ul><p><strong>开放问题与讨论</strong>:</p><ul><li>性能分析工具（Flame graphs）的适用性及改进建议。</li><li>内存局部性（Cross-CPU操作）的验证。</li></ul><p><strong>后续行动计划</strong>:</p><ul><li>PG合并功能开发、Systore集成测试、EC Pool通用代码合并、性能数据发布、用户指南文档分离等。</li></ul><p><strong>其他资源</strong>:</p><ul><li>Slack频道、GitHub Tracker、周会等。</li></ul><p><strong>会议结束时间</strong>: [具体时间]</p><p><strong>备注</strong>: 请与会成员在Etherpad补充遗漏内容，后续通过邮件同步更新。</p>",18)])])}const S=l(t,[["render",s]]);export{_ as __pageData,S as default};
